// A person's tag is s-<first 8 hex of their Jellyfin user id>; it goes on every movie and series
// they requested or watchlisted in Seerr and on the collections those are in. Tags of that shape are
// this workflow's, every other tag stays. A Jellyfin user whose "Allow items with tags" holds
// `scoped` gets their own tag added there. Called by Jellyfin's webhook, it tags only the added title
// and adds its tags to its collections; otherwise it sets everything anew.
// a host without Seerr's or Jellyfin's key has nothing to tag
if (!$env.REQUESTS_API_KEY || !$env.JELLYFIN_API_KEY) return [];
const helpers = this.helpers;
const MARKER = 'scoped';
// f-<8 hex>: an older tag of this kind, removed wherever found
const OURS = /^[sf]-[0-9a-f]{8}$/i;
// a request the owner declined grants nothing (Seerr's MediaRequestStatus)
const DECLINED = 3;
const PAGE = 100;
// The fields POST /Items/{id} reads (Jellyfin's ItemUpdateController.UpdateItem). It overwrites each
// scalar with what it is sent, null too, and fails on the whole item as GET returns it (trickplay),
// so these go back as they came. People stays out: sent, it rewrites the cast and crew.
const EDITABLE = [
  'AirDays', 'AirTime', 'AirsAfterSeasonNumber', 'AirsBeforeEpisodeNumber', 'AirsBeforeSeasonNumber',
  'Album', 'AlbumArtists', 'ArtistItems', 'AspectRatio', 'CommunityRating', 'CriticRating',
  'CustomRating', 'DateCreated', 'DisplayOrder', 'EndDate', 'ForcedSortName', 'Genres', 'Height',
  'IndexNumber', 'LockData', 'LockedFields', 'Name', 'OfficialRating', 'OriginalLanguage',
  'OriginalTitle', 'Overview', 'ParentIndexNumber', 'PreferredMetadataCountryCode',
  'PreferredMetadataLanguage', 'PremiereDate', 'ProductionLocations', 'ProductionYear', 'ProviderIds',
  'RunTimeTicks', 'SeriesName', 'Status', 'Studios', 'Taglines', 'Tags', 'Video3DFormat',
];

const api = (url, headers) => (method, path, qs, body) =>
  helpers.httpRequest({ method, url: url + path, qs, body, headers, json: true, timeout: 120000 });
const seerr = api('http://127.0.0.1:5055', { 'X-Api-Key': $env.REQUESTS_API_KEY });
const jellyfin = api('http://127.0.0.1:8096', {
  Authorization: `MediaBrowser Token="${$env.JELLYFIN_API_KEY}"`,
});

// Jellyfin ids with or without dashes, the way its API writes them
const plain = id => id.replace(/-/g, '').toLowerCase();
const tagOf = userId => 's-' + plain(userId).slice(0, 8);
const ours = tags => new Set((tags || []).filter(tag => OURS.test(tag)).map(tag => tag.toLowerCase()));
const sorted = set => [...set].sort();

async function pages(path, qs) {
  const results = [];
  for (let skip = 0; ; skip += PAGE) {
    const page = await seerr('GET', path, { ...qs, take: PAGE, skip });
    results.push(...page.results);
    if (skip + PAGE >= page.pageInfo.results) return results;
  }
}

async function watchlist(userId) {
  const results = [];
  for (let page = 1; ; page++) {
    const result = await seerr('GET', `/api/v1/user/${userId}/watchlist`, { page });
    results.push(...result.results);
    if (page >= result.totalPages) return results;
  }
}

// [tag, entry] for every title each person requested or has on their watchlist
async function wanted() {
  const found = [];
  for (const user of await pages('/api/v1/user', {})) {
    if (!user.jellyfinUserId) continue;
    const tag = tagOf(user.jellyfinUserId);
    for (const request of await pages('/api/v1/request', { filter: 'all', requestedBy: user.id })) {
      if (request.status !== DECLINED) found.push([tag, request]);
    }
    for (const entry of await watchlist(user.id)) found.push([tag, entry]);
  }
  return found;
}

// kind:provider:id -> Jellyfin item id, from the ids Jellyfin keeps for each title
function providerIndex(library) {
  const index = new Map();
  for (const item of library) {
    const kind = item.Type === 'Movie' ? 'movie' : 'tv';
    for (const [provider, value] of Object.entries(item.ProviderIds || {})) {
      index.set(`${kind}:${provider.toLowerCase()}:${value}`, plain(item.Id));
    }
  }
  return index;
}

// The Jellyfin items a request or watchlist entry stands for: Seerr's link, and the title's
// TMDb/TVDB ids found in Jellyfin, so an item counts before Seerr's scan links it.
function resolve(entry, index) {
  const media = entry.media || {};
  const kind = media.mediaType || entry.mediaType;
  const ids = new Set(
    ['jellyfinMediaId', 'jellyfinMediaId4k'].filter(key => media[key]).map(key => plain(media[key])),
  );
  for (const provider of ['tmdb', 'tvdb']) {
    const value = media[`${provider}Id`] || entry[`${provider}Id`];
    const id = value && index.get(`${kind}:${provider}:${value}`);
    if (id) ids.add(id);
  }
  return ids;
}

const users = await jellyfin('GET', '/Users');
const admin = users.find(user => user.Policy.IsAdministrator)?.Id;
if (!admin) throw new Error('Jellyfin has no administrator to read the library as');
const items = async qs =>
  (await jellyfin('GET', '/Items', {
    userId: admin, fields: 'Tags,ProviderIds', enableImages: false, enableUserData: false, ...qs,
  })).Items;

const added = $('Item added').isExecuted;
let library;
if (added) {
  let body = $('Item added').first().json.body;
  // the Webhook plugin sends text/plain unless its destination sets a Content-Type header
  if (typeof body === 'string') body = JSON.parse(body);
  if (!body?.ItemId) throw new Error('Item added: no ItemId in the body; template {"ItemId":"{{ItemId}}"}');
  let [item] = await items({ ids: plain(body.ItemId) });
  // episodes and seasons show through their series
  if (item?.SeriesId) [item] = await items({ ids: item.SeriesId });
  library = item && ['Movie', 'Series'].includes(item.Type) ? [item] : [];
  if (!library.length) return [];
} else {
  library = await items({ includeItemTypes: 'Movie,Series', recursive: true });
}

const index = providerIndex(library);
const asked = new Map();
for (const [tag, entry] of await wanted()) {
  for (const id of resolve(entry, index)) {
    if (!asked.has(id)) asked.set(id, new Set());
    asked.get(id).add(tag);
  }
}
const want = item => asked.get(plain(item.Id)) || new Set();

const desired = new Map(library.map(item => [plain(item.Id), want(item)]));
// an added title nobody asked for changes no collection
const collections = added && !want(library[0]).size
  ? []
  : await items({ includeItemTypes: 'BoxSet', recursive: true });
const relevant = [];
for (const collection of collections) {
  const children = await items({ parentId: collection.Id });
  if (added) {
    if (!children.some(child => plain(child.Id) === plain(library[0].Id))) continue;
    // the other children's tags stay
    const kept = [...ours(collection.Tags)].filter(tag => tag.startsWith('s-'));
    desired.set(plain(collection.Id), new Set([...kept, ...want(library[0])]));
  } else {
    desired.set(plain(collection.Id), new Set(children.flatMap(child => [...want(child)])));
  }
  relevant.push(collection);
}

const changes = [];
for (const item of [...library, ...relevant]) {
  const have = ours(item.Tags);
  const tags = desired.get(plain(item.Id));
  const plus = sorted(tags).filter(tag => !have.has(tag));
  const minus = sorted(have).filter(tag => !tags.has(tag));
  if (!plus.length && !minus.length) continue;
  const current = await jellyfin('GET', `/Items/${item.Id}`, { userId: admin });
  const update = Object.fromEntries(
    EDITABLE.filter(field => field in current).map(field => [field, current[field]]),
  );
  update.Tags = [...(current.Tags || []).filter(tag => !OURS.test(tag)), ...sorted(tags)];
  await jellyfin('POST', `/Items/${item.Id}`, undefined, update);
  changes.push({ json: { name: item.Name ?? item.Id, add: plus, remove: minus } });
}

if (added) return changes;
for (const user of users) {
  const allowed = (user.Policy.AllowedTags || []).map(tag => tag.toLowerCase());
  const tag = tagOf(user.Id);
  // its f- tag, replaced
  const old = 'f-' + tag.slice(2);
  if (!allowed.includes(MARKER) || (allowed.includes(tag) && !allowed.includes(old))) continue;
  const { Policy: policy } = await jellyfin('GET', `/Users/${user.Id}`);
  const others = (policy.AllowedTags || []).filter(t => ![old, tag].includes(t.toLowerCase()));
  policy.AllowedTags = [...others, tag];
  await jellyfin('POST', `/Users/${user.Id}/Policy`, undefined, policy);
  changes.push({
    json: {
      name: `user ${user.Name}`,
      add: allowed.includes(tag) ? [] : [tag],
      remove: allowed.includes(old) ? [old] : [],
    },
  });
}
return changes;
